    "prompt": "What is an immutable class and how do you write one?",
    "answerHtml": "<div class=\"hl\"><pre><span></span><code><span class=\"kd\">public</span><span class=\"w\"> </span><span class=\"kd\">final</span><span class=\"w\"> </span><span class=\"kd\">class</span> <span class=\"nc\">Money</span><span class=\"w\"> </span><span class=\"p\">{</span><span class=\"w\">                        </span><span class=\"c1\">// 1. final class</span>\n<span class=\"w\">    </span><span class=\"kd\">private</span><span class=\"w\"> </span><span class=\"kd\">final</span><span class=\"w\"> </span><span class=\"n\">BigDecimal</span><span class=\"w\"> </span><span class=\"n\">amount</span><span class=\"p\">;</span><span class=\"w\">              </span><span class=\"c1\">// 2. final private fields</span>\n<span class=\"w\">    </span><span class=\"kd\">private</span><span class=\"w\"> </span><span class=\"kd\">final</span><span class=\"w\"> </span><span class=\"n\">List</span><span class=\"o\">&lt;</span><span class=\"n\">String</span><span class=\"o\">&gt;</span><span class=\"w\"> </span><span class=\"n\">tags</span><span class=\"p\">;</span>\n<span class=\"w\">    </span><span class=\"kd\">public</span><span class=\"w\"> </span><span class=\"nf\">Money</span><span class=\"p\">(</span><span class=\"n\">BigDecimal</span><span class=\"w\"> </span><span class=\"n\">amount</span><span class=\"p\">,</span><span class=\"w\"> </span><span class=\"n\">List</span><span class=\"o\">&lt;</span><span class=\"n\">String</span><span class=\"o\">&gt;</span><span class=\"w\"> </span><span class=\"n\">tags</span><span class=\"p\">)</span><span class=\"w\"> </span><span class=\"p\">{</span>\n<span class=\"w\">        </span><span class=\"k\">this</span><span class=\"p\">.</span><span class=\"na\">amount</span><span class=\"w\"> </span><span class=\"o\">=</span><span class=\"w\"> </span><span class=\"n\">amount</span><span class=\"p\">;</span>\n<span class=\"w\">        </span><span class=\"k\">this</span><span class=\"p\">.</span><span class=\"na\">tags</span><span class=\"w\"> </span><span class=\"o\">=</span><span class=\"w\"> </span><span class=\"n\">List</span><span class=\"p\">.</span><span class=\"na\">copyOf</span><span class=\"p\">(</span><span class=\"n\">tags</span><span class=\"p\">);</span><span class=\"w\">            </span><span class=\"c1\">// 3. defensive copy in</span>\n<span class=\"w\">    </span><span class=\"p\">}</span>\n<span class=\"w\">    </span><span class=\"kd\">public</span><span class=\"w\"> </span><span class=\"n\">List</span><span class=\"o\">&lt;</span><span class=\"n\">String</span><span class=\"o\">&gt;</span><span class=\"w\"> </span><span class=\"nf\">getTags</span><span class=\"p\">()</span><span class=\"w\"> </span><span class=\"p\">{</span><span class=\"w\"> </span><span class=\"k\">return</span><span class=\"w\"> </span><span class=\"n\">tags</span><span class=\"p\">;</span><span class=\"w\"> </span><span class=\"p\">}</span><span class=\"c1\">// 4. unmodifiable out</span>\n<span class=\"w\">    </span><span class=\"c1\">// 5. no setters</span>\n<span class=\"p\">}</span>\n</code></pre></div>",
